<script lang="ts">
	let { data, form } = $props();
	const engine=data.engine;
	const cfg=engine.id==='studio'?data.settings?.settings:data.settings;
	const mcpPolicy=data.mcpPolicy||{oss:{enabled:true,allowedStrengths:['low','medium','high','custom1','custom2'],maxBundlesPerPreset:20},ccs:{enabled:true,maxBundlesPerWorkspace:100,maxEntriesPerBundle:500,maxDependenciesPerBundle:50,maxDependencyDepth:8,allowProfiles:true}};
	const pct=(value:unknown,fallback=50)=>Math.round(Number(value??fallback/100)*100);
	const core=data.processingCore||null;
	const setupComplete=engine.setupState==='complete';
</script>

<svelte:head><title>{engine.name} Configuration · OrbitFS Engine Host</title><meta name="robots" content="noindex,nofollow" /></svelte:head>

<div class="shell">
	<header><a class="brand" href="/engines">OrbitFS Engine Host</a><nav><a href={`/engines/${engine.id}`}>← {engine.name}</a><span>Configuration</span></nav></header>
	<main>
		<div class="toolbar"><a class="back" href={`/engines/${engine.id}`}>← Back to {engine.name}</a></div>
		<div class="hero"><div><small>ENGINE CONFIGURATION</small><h1>{engine.fullName}</h1><p>Settings used by the live Engine runtime. Changes are stored in the shared OrbitFS backend.</p></div><span>{engine.engineState}</span></div>

		{#if form?.error}<div class="notice error"><b>Configuration error</b><span>{form.error}</span></div>{/if}
		{#if form?.message}<div class="notice ok">{form.message}</div>{/if}
		{#if !engine.attached||!engine.linked}<div class="notice error">Attach and link this Engine from Panel before changing configuration.</div>{/if}

		<div class="facts">
			<span><small>Host</small><b>{engine.hostUrl||'Not linked'}</b></span>
			<span><small>Panel</small><b>{engine.panelUrl||'Not linked'}</b></span>
			<span><small>Workspace</small><b>{engine.workspaceName||engine.workspaceId||'Not assigned'}</b></span>
			<span><small>Setup</small><b>{String(engine.setupState||'not_started').replaceAll('_',' ')}</b></span>
		</div>

		{#if engine.id==='mcp'&&cfg}
			<form method="POST" action="?/save" class="form">
				<div class="two-col">
					<section><h2>OAuth and client access</h2><p>Authentication and client behaviour for MCP connections.</p><div class="grid three"><label><span>Access token lifetime</span><input type="number" name="accessTokenMinutes" min="5" max="1440" value={cfg.accessTokenMinutes}/><small>Minutes</small></label><label><span>Refresh token lifetime</span><input type="number" name="refreshTokenDays" min="1" max="90" value={cfg.refreshTokenDays}/><small>Days</small></label><label><span>Authorization code lifetime</span><input type="number" name="authorizationCodeMinutes" min="1" max="30" value={cfg.authorizationCodeMinutes}/><small>Minutes</small></label></div><div class="checks"><label><input type="checkbox" name="dynamicClientRegistration" checked={cfg.dynamicClientRegistration}/><span><b>Dynamic client registration</b><small>Allow compatible clients to register through OrbitFS OAuth.</small></span></label><label><input type="checkbox" name="allowWriteScope" checked={cfg.allowWriteScope}/><span><b>Allow write scope</b><small>Permit clients to request orbitfs:write.</small></span></label><label><input type="checkbox" name="allowOfflineAccess" checked={cfg.allowOfflineAccess}/><span><b>Allow offline access</b><small>Permit refresh-token based access.</small></span></label></div></section>
					<section><h2>Transport</h2><p>Controls the live MCP endpoint.</p><div class="grid"><label><span>Maximum request size</span><input type="number" name="maxRequestKb" min="64" max="16384" value={cfg.maxRequestKb}/><small>KB</small></label></div><div class="checks"><label><input type="checkbox" name="requireJsonContentType" checked={cfg.requireJsonContentType}/><span><b>Require JSON POST bodies</b></span></label><label><input type="checkbox" name="allowDeleteTransport" checked={cfg.allowDeleteTransport}/><span><b>Allow DELETE/session termination</b></span></label><label><input type="checkbox" name="mirrorUiState" checked={cfg.mirrorUiState}/><span><b>Expose UI state in structured responses</b></span></label><label><input type="checkbox" name="logRejectedRequests" checked={cfg.logRejectedRequests}/><span><b>Log rejected requests</b></span></label></div></section>
					<section><h2>OSS hard limits</h2><p>Administrator limits applied to Panel OSS and enforced again by the MCP runtime.</p><div class="checks"><label><input type="checkbox" name="ossEnabled" checked={mcpPolicy.oss?.enabled!==false}/><span><b>Allow OSS startup</b><small>Master switch for MCP startup presets.</small></span></label></div><div class="grid"><label><span>Maximum CCS bundles per preset</span><input type="number" name="maxBundlesPerPreset" min="1" max="100" value={mcpPolicy.oss?.maxBundlesPerPreset||20}/></label></div><div class="strengths"><small>Allowed startup strengths</small><div class="checks compact">{#each ['low','medium','high','custom1','custom2'] as key}<label><input type="checkbox" name={`ossStrength_${key}`} checked={(mcpPolicy.oss?.allowedStrengths||[]).includes(key)}/><span><b>{key}</b></span></label>{/each}</div></div></section>
					<section><h2>CCS hard limits</h2><p>Caps context growth before a user can create an oversized or deeply nested context graph.</p><div class="checks"><label><input type="checkbox" name="ccsEnabled" checked={mcpPolicy.ccs?.enabled!==false}/><span><b>Allow CCS</b></span></label><label><input type="checkbox" name="ccsAllowProfiles" checked={mcpPolicy.ccs?.allowProfiles!==false}/><span><b>Allow Profiles in CCS</b></span></label></div><div class="grid two"><label><span>Bundles per workspace</span><input type="number" name="maxBundlesPerWorkspace" min="1" max="1000" value={mcpPolicy.ccs?.maxBundlesPerWorkspace||100}/></label><label><span>Entries per bundle</span><input type="number" name="maxEntriesPerBundle" min="1" max="5000" value={mcpPolicy.ccs?.maxEntriesPerBundle||500}/></label><label><span>Dependencies per bundle</span><input type="number" name="maxDependenciesPerBundle" min="0" max="500" value={mcpPolicy.ccs?.maxDependenciesPerBundle??50}/></label><label><span>Maximum dependency depth</span><input type="number" name="maxDependencyDepth" min="1" max="32" value={mcpPolicy.ccs?.maxDependencyDepth||8}/></label></div></section>
				</div>
				<div class="savebar"><span>Runtime + hard policy. Customer-facing OSS/CCS/Projects settings stay in Panel.</span><button class="primary" disabled={!engine.attached||!engine.linked}>Save MCP configuration</button></div>
			</form>
		{:else if engine.id==='apex'&&cfg}
			<section class="core-card">
				<div class="section-title"><div><h2>APEX processing core</h2><p>The shared core is serverless state used by APEX. It does not require another deployment.</p></div><span class:good={core?.initialized}>{core?.initialized?'Initialized':'Not initialized'}</span></div>
				<div class="readout"><span><small>Version</small><b>{core?.version||'—'}</b></span><span><small>Storage</small><b>{core?.storage||'Supabase'}</b></span><span><small>Processing owner</small><b>{core?.processingOwner||'engine-host'}</b></span><span><small>Knowledge owner</small><b>{core?.knowledgeOwner||'panel-library'}</b></span></div>
				{#if engine.attached&&engine.linked}<form method="POST" action="?/core"><button>{core?.initialized?'Verify processing core':'Initialize processing core'}</button></form>{/if}
			</section>

			<form method="POST" action="?/save" class="form">
				<div class="two-col">
					<section><h2>Execution policy</h2><p>Controls when APEX accepts processing and routing work.</p><div class="grid two"><label><span>Request mode</span><select name="serviceMode"><option value="on_demand" selected={cfg.serviceMode!=='automatic'}>On demand only</option><option value="automatic" selected={cfg.serviceMode==='automatic'}>Allow automatic callers</option></select></label><label><span>Idle timeout</span><input name="idleTimeoutSeconds" type="number" min="5" max="300" value={Math.round(Number(cfg.idleTimeoutMs||10000)/1000)}/><small>Seconds</small></label></div><div class="checks"><label><input name="standby" type="checkbox" checked={cfg.standby!==false}/><span><b>Allow Standby</b><small>Allow on-demand standby behaviour.</small></span></label><label><input name="blockAutomation" type="checkbox" checked={cfg.blockAutomation===true}/><span><b>Block automatic routing</b></span></label><label><input name="fullShutdown" type="checkbox" checked={cfg.fullShutdown===true}/><span><b>Disable APEX processing</b></span></label></div></section>
					<section><h2>Knowledge import defaults</h2><p>Defaults for source assets submitted by Panel.</p>{#if data.processingSettings}<div class="grid two"><label><span>Default import mode</span><select name="importMode"><option value="knowledge" selected={data.processingSettings.importMode==='knowledge'}>Knowledge</option><option value="reference" selected={data.processingSettings.importMode==='reference'}>Reference</option><option value="draft" selected={data.processingSettings.importMode==='draft'}>Draft</option></select></label><label><span>Maximum source size</span><input name="maxSourceMb" type="number" min="1" max="250" value={Math.round(Number(data.processingSettings.maxSourceBytes||52428800)/1048576)}/><small>MB</small></label><label><span>Chunk target</span><input name="chunkTargetChars" type="number" min="1000" max="16000" value={data.processingSettings.chunkTargetChars||4000}/></label><label><span>Chunk overlap</span><input name="chunkOverlapChars" type="number" min="0" max="2000" value={data.processingSettings.chunkOverlapChars||400}/></label></div><div class="checks"><label><input name="autoCreateNew" type="checkbox" checked={data.processingSettings.autoCreateNew!==false}/><span><b>Auto-create new Knowledge</b></span></label><label><input name="normalize" type="checkbox" checked={data.processingSettings.normalize!==false}/><span><b>Normalize extracted text</b></span></label></div>{:else}<div class="empty">Initialize the APEX processing core to create workspace processing defaults.</div>{/if}</section>
					<section><h2>Routing targets</h2><p>Panel-owned destinations APEX may suggest. Existing records remain approval-first.</p>{#if data.processingSettings}<div class="checks"><label><input name="routingKnowledgeArchitecture" type="checkbox" checked={data.processingSettings.routing?.knowledgeArchitecture!==false}/><span><b>Knowledge architecture</b></span></label><label><input name="routingProjects" type="checkbox" checked={data.processingSettings.routing?.projects!==false}/><span><b>Projects</b></span></label><label><input name="routingProfiles" type="checkbox" checked={data.processingSettings.routing?.profiles!==false}/><span><b>Profiles</b></span></label></div>{/if}</section>
					<section><h2>Storage contract</h2><p>APEX extracts and processes. Panel Library remains canonical.</p><div class="rows"><div><span>Compute</span><b>Vercel</b></div><div><span>Database</span><b>Shared Supabase</b></div><div><span>Filesystem</span><b>None</b></div><div><span>Canonical Knowledge</span><b>Panel Library</b></div></div></section>
				</div>
				<div class="savebar"><span>{core?.initialized?'Core ready for configuration.':'Initialize the processing core first.'}</span><button class="primary" disabled={!engine.attached||!engine.linked||!core?.initialized}>Save APEX configuration</button></div>
			</form>
		{:else if engine.id==='studio'&&cfg}
			<form method="POST" action="?/save" class="form"><section><h2>Studio routing</h2><div class="checks"><label><input name="routingEnabled" type="checkbox" checked={cfg.routingEnabled!==false}/><span><b>Enable routing</b></span></label><label><input name="routingAutoAnalyzeCreate" type="checkbox" checked={cfg.routingAutoAnalyzeCreate!==false}/><span><b>Analyse new content</b></span></label><label><input name="routingAutoAnalyzeUpdate" type="checkbox" checked={cfg.routingAutoAnalyzeUpdate!==false}/><span><b>Re-analyse updates</b></span></label></div><div class="grid three"><label><span>General confidence %</span><input name="routingMinConfidencePercent" type="number" min="0" max="100" value={pct(cfg.routingMinConfidence)}/></label><label><span>Max suggestions</span><input name="routingMaxSuggestions" type="number" min="1" max="20" value={cfg.routingMaxSuggestions||5}/></label><label><span>Max characters</span><input name="routingMaxCharacters" type="number" min="1000" max="200000" value={cfg.routingMaxCharacters||50000}/></label></div></section><div class="savebar"><span>Studio settings</span><button class="primary" disabled={!engine.attached||!engine.linked}>Save Studio configuration</button></div></form>
		{/if}

		<div class="links"><a href={`/engines/${engine.id}`}>Engine home</a>{#if !setupComplete}<a href={`/engines/${engine.id}/setup`}>Continue setup</a>{:else}<a href={`/engines/${engine.id}/setup`}>Run setup again</a>{/if}<a href={`/engines/${engine.id}/connections`}>Connections</a>{#if engine.id==='mcp'}<a href={`/engines/${engine.id}/oauth`}>OAuth clients</a>{/if}<a href={`/engines/${engine.id}/runtime`}>Runtime</a><a href={`/engines/${engine.id}/diagnostics`}>Diagnostics</a></div>
	</main>
</div>

