x}.two-col{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}section{border:1px solid #252a30;background:#0d1014;border-radius:9px;padding:17px;min-width:0}section h2{font-size:15px;margin:0 0 5px}section>p,.section-title p{margin:0 0 13px;color:#7f868f;font-size:10px;line-height:1.5}.section-title{display:flex;justify-content:space-between;gap:12px;align-items:start}.section-title>span{font-size:9px;border:1px solid #414850;padding:6px 8px;border-radius:999px;white-space:nowrap}.section-title>span.good{border-color:#2d6846;color:#91deb0}.grid{display:grid;grid-template-columns:1fr;gap:10px}.grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}.grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}label>span{display:block;font-size:9px;color:#a6acb3;margin-bottom:5px}input[type='number'],select{box-sizing:border-box;width:100%;border:1px solid #343a42;background:#11151a;color:#e3e6e9;border-radius:6px;padding:9px 10px;font-size:10px}label>small{display:block;color:#6f767e;font-size:8px;margin-top:4px}.checks{display:grid;gap:7px;margin-top:11px}.checks>label{display:grid;grid-template-columns:18px 1fr;gap:8px;align-items:start;border-top:1px solid #23272d;padding-top:8px}.checks input{margin-top:1px}.checks b{font-size:10px}.checks small{display:block;color:#737a82;font-size:8px;margin-top:2px}.checks.compact{grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}.strengths{margin-top:12px}.strengths>small{font-size:9px;color:#a6acb3}.readout{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid #252a30;margin:12px 0;border-radius:7px;overflow:hidden}.core-card{margin-bottom:14px}.core-card button,.savebar button,.links a{border:1px solid #373d45;background:#15191e;color:#ddd;text-decoration:none;padding:8px 11px;border-radius:6px;font-size:9px;cursor:pointer}.savebar{position:sticky;bottom:10px;z-index:12;display:flex;justify-content:space-between;align-items:center;gap:14px;border:1px solid #30363d;background:#0d1116eF;p