	@media(max-width:820px){header{padding:0 14px}nav span{display:none}main{padding:18px 12px 50px}.hero{align-items:flex-start;flex-direction:column}.hero h1{font-size:25px}.facts,.readout{grid-template-columns:repeat(2,minmax(0,1fr))}.facts span:nth-child(2),.readout span:nth-child(2){border-right:0}.facts span:nth-child(-n+2),.readout span:nth-child(-n+2){border-bottom:1px solid #252a30}.two-col,.grid.two,.grid.three{grid-template-columns:1fr}.checks.compact{grid-template-columns:1fr}.savebar{position:static;flex-direction:column;align-items:stretch}.savebar button{width:100%}.links{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.links a{text-align:center}.toolbar{position:sticky;top:62px;z-index:10}.back{background:#0d1014}.section-title{flex-direction:column}.rows>div{grid-template-columns:1fr;gap:3px}}
	@media(max-width:430px){.links{grid-template-columns:1fr}.facts,.readout{grid-template-columns:1fr}.facts span,.readout span{border-right:0!important;border-bottom:1px solid #252a30}.facts span:last-child,.readout span:last-child{border-bottom:0}}
</style>